import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/commands.md","filePath":"modules/corelib/commands.md","lastUpdated":0}`),a={name:`modules/corelib/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>CoreLib 的全部命令和权限节点如下, 再挑几个常用操作, 一步步说明怎么用</p><p>EmakiCoreLib 的主命令是 <code>/emakicorelib</code>, 别名为 <code>/corelib</code>, <code>/emakicore</code>. 这些命令主要给你这样的服务器管理员用: 重载 CoreLib, 做配置预检 (提前把配置检查一遍), 查看或执行已注册的 Action (动作, 即动作系统里注册的一段效果), 以及排查循环 Action 任务</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td><code>/corelib reload</code></td><td>重新加载 CoreLib 的配置和 Action 系统; 如果预检没通过, 这次重载会取消, 继续用原来的配置</td><td><code>emakicorelib.reload</code> 或 <code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib check [module|report|--fix]</code></td><td>做一次配置预检, 可以只检查指定模块, 也可以看最近一次的检查报告; <code>--fix</code> 会真的执行自动修复 (补缺失的配置文件, 目录和键), 修完打印修复与失败统计并自动复检</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib action list</code></td><td>列出当前注册表里各段的 id, kind (段的类型, 取 <code>source</code>/<code>gate</code>/<code>action</code>) 和 owner</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib action run &lt;actionId&gt; key=value ...</code></td><td>直接执行一条已经注册的 Action; 也可以省掉 <code>run</code>, 写成 <code>/corelib action &lt;actionId&gt; key=value ...</code></td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib pdc-convert &lt;players|containers|entities|all&gt; [--dry-run]</code></td><td>把历史的带点 PDC 键 (用 <code>.</code> 分段的老键) 换成扁平键 (用 <code>_</code> 分段的新键); 加 <code>--dry-run</code> 只统计不写入</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib debug all [on|off|status]</code></td><td>在运行时切换全局 Debug 开关; 不带参数就等同于 <code>status</code>. 重载后恢复成 <code>debug.global_all</code> 的配置值</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib debug loops [list|player|key|cancel|cancel-player]</code></td><td>查看正在跑的循环 Action 任务, 并按 key 或按玩家取消循环任务</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib help</code></td><td>显示各子命令的帮助; 不带参数, 或者输入了不认识的子命令时也会显示</td><td>无</td></tr></tbody></table><p>记法很简单: <code>action</code> 子命令也可以写作 <code>actions</code>, 两者等价</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakicorelib.reload</code></td><td>op</td><td>允许重载 CoreLib</td></tr><tr><td><code>emakicorelib.admin</code></td><td>op</td><td>CoreLib 的管理员总权限, 包含 <code>emakicorelib.reload</code></td></tr></tbody></table><h2 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to “常用操作”">​</a></h2><h3 id="重载-corelib" tabindex="-1">重载 CoreLib <a class="header-anchor" href="#重载-corelib" aria-label="Permalink to “重载 CoreLib”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib reload</span></span></code></pre></div><p>改完 CoreLib 主配置, 语言文件或 Action 之后, 你运行它即可. 它会先跑一遍配置预检; 预检没过, 就不会替换当前正在生效的配置</p><h3 id="执行配置预检" tabindex="-1">执行配置预检 <a class="header-anchor" href="#执行配置预检" aria-label="Permalink to “执行配置预检”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib check</span></span>
<span class="line"><span>/corelib check report</span></span>
<span class="line"><span>/corelib check corelib</span></span>
<span class="line"><span>/corelib check --fix</span></span></code></pre></div><p><code>check</code> 会检查配置引用, Action 模板, 物品源和 CoreLib 相关配置. 想看最近一次预检的结果, 用 <code>report</code>; 只想检查某个模块, 就传入它的模块 ID. 加上 <code>--fix</code> 会直接落盘修复, 只处理三类可自动修复的问题: 缺失默认配置文件, 缺失目录, 缺失配置键. 修完会打印修复与失败统计, 并自动再跑一次预检给出结果. 已经存在且被服主改过的内容不会被覆盖. 修好的文件要等对应模块执行 reload 或重启服务器后才生效</p><h3 id="查看和执行已注册-action" tabindex="-1">查看和执行已注册 Action <a class="header-anchor" href="#查看和执行已注册-action" aria-label="Permalink to “查看和执行已注册 Action”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib action list</span></span>
<span class="line"><span>/corelib action run send_message text=&quot;hello&quot;</span></span></code></pre></div><p><code>action list</code> 帮你确认当前注册表里有哪些段, 每行输出 id, kind 和 owner 三项. <code>action run</code> 会把整行交给管道编译器按普通管道行解析, 所以参数, 引号, <code>if &lt;条件&gt; [ ... ]</code> 分支和 gate 写法都和你在配置文件里写的管道行一样. 注意在控制台执行时没有玩家上下文, 依赖玩家的段会按原有的校验失败</p><h3 id="转换历史-pdc-键" tabindex="-1">转换历史 PDC 键 <a class="header-anchor" href="#转换历史-pdc-键" aria-label="Permalink to “转换历史 PDC 键”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib pdc-convert players</span></span>
<span class="line"><span>/corelib pdc-convert containers</span></span>
<span class="line"><span>/corelib pdc-convert entities</span></span>
<span class="line"><span>/corelib pdc-convert all --dry-run</span></span></code></pre></div><p>先选 scope (扫描范围), 取值为 <code>players</code>, <code>containers</code>, <code>entities</code>, <code>all</code>. 转换在异步线程上扫描, 结束后按 scope 输出 scanned / migrated / skipped / failed 计数和总迁移数. 建议先加 <code>--dry-run</code> 只统计不写入, 先估一下影响面</p><h3 id="排查循环-action" tabindex="-1">排查循环 Action <a class="header-anchor" href="#排查循环-action" aria-label="Permalink to “排查循环 Action”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib debug loops list</span></span>
<span class="line"><span>/corelib debug loops player Steve</span></span>
<span class="line"><span>/corelib debug loops key some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel-player Steve</span></span></code></pre></div><p>这些命令只用来排查或清理循环 Action. 注意: 生产服上不建议长期保留大量循环任务的调试输出</p><h3 id="切换全局-debug" tabindex="-1">切换全局 Debug <a class="header-anchor" href="#切换全局-debug" aria-label="Permalink to “切换全局 Debug”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib debug all status</span></span>
<span class="line"><span>/corelib debug all on</span></span>
<span class="line"><span>/corelib debug all off</span></span></code></pre></div><p>它的作用等同于临时改写 <code>config.yml</code> 里的 <code>debug.global_all</code>, 会影响所有使用 CoreLib <code>DebugLogger</code> 的 Emaki 模块. 注意这个切换不会写回配置文件, 你执行 <code>/corelib reload</code> 后会重新采用配置值</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};